CATALOG = {
    language: {row[0]: row[index] for row in TABELA}
    for index, language in enumerate(LANGUAGES)
}


def merge_catalog(catalog=None):
    """Return host-compatible locale dictionaries without mutating the input."""
    merged = {language: dict(phrases) for language, phrases in (catalog or {}).items()}
    for language, phrases in CATALOG.items():
        merged.setdefault(language, {}).update(phrases)
    return merged
